static SDL_FColor projectile_colour(const Obj*o,int hostile){static const SDL_FColor colours[12]={{.12f,.45f,1,1},{1,.3f,.04f,1},{.7f,.12f,1,1},{.1f,.85f,1,1},{.35f,1,.08f,1},{1,.72f,.1f,1},{.4f,1,.2f,1},{1,.34f,.07f,1},{1,.15f,.75f,1},{.24f,.52f,1,1},{1,.12f,.15f,1},{1,.62f,.06f,1}};SDL_FColor c=colours[projectile_tint(o,hostile)];if(hostile&&organic_context()&&o->type>=2){c=o->type==2?(SDL_FColor){.85f,.55f,.2f,1}:o->type==4||o->type==6||o->type==9?(SDL_FColor){.85f,.25f,.6f,1}:(SDL_FColor){.45f,1,.2f,1};}if(!hostile&&(g.chassis||g.variantEquip[clamp(o->type,0,8)])){int v=g.variantEquip[clamp(o->type,0,8)];static const SDL_FColor hue[3][3]={{{.2f,.65f,1,1},{.3f,1,1,1},{1,.65f,.2f,1}},{{.1f,1,.5f,1},{.65f,1,.1f,1},{.2f,.7f,1,1}},{{1,.15f,.1f,1},{1,.7f,.1f,1},{1,.1f,.65f,1}}};c=hue[g.chassis][v];}return c;}
