static float planet_height(int phase){if(phase<6||phase>11)return .5f;static const float altitude[6]={.8f,.35f,.15f,.6f,1,.45f};int beat=g.clock/400,slot=(beat+phase)%6;float t=(g.clock%400)/400.0f;t=t*t*(3-2*t);return altitude[slot]+(altitude[(slot+1)%6]-altitude[slot])*t;}
static float ground_scale(int phase){return phase>=6&&phase<=11?1.65f-.85f*planet_height(phase):1;}
static float cloud_pass(int phase){return fmaxf(0,1-fabsf(planet_height(phase)-.5f)*2);}
static float environment_rate(void){float rate=fminf(16,fmaxf(.2f,ex.scrollSpeed/(cavern_phase(ex.phase)?384.0f:192.0f))),battle=ex.bossSpawned?1:ex.bossWarning?(100-ex.bossWarning)/100.0f:0;battle=battle*battle*(3-2*battle);return rate+(fminf(rate,.22f)-rate)*battle;}
static float foreground_speed(void){int p=ex.phase;return p>=12?440:p==4?650:p==10?3100:p>=6?1920:360;}
/* Convert the visible foreground velocity back through the camera's Y scale.
   Both smoke and flame therefore travel with the current cloud/ground layer. */
static float wake_speed(void){return foreground_speed()*environment_rate()/(3*(696+264*sideBlend)/696);}

void pc_burst(int x,int y,int big){lastExplosionX=(float)x;if(!g.fx)return;int n=(int)((big?330:100)*intensity()*(quality==2?1:quality==1?.5f:.15f));for(int i=0;i<n;i++){float a=frand()*2*PI,s=8+frand()*(big?130:65);emit(x,y,cosf(a)*s,sinf(a)*s,.25f+frand()*(big?1.8f:.9f),.35f+frand()*2.5f,(i&7)?1:3);}Wave*w=waves+waveHead;waveHead=(waveHead+1)%64;*w=(Wave){x,y,0,big?1.4f:.65f,big?130:60,big};}
void pc_heatseeker_blast(int x,int y,int radius){pc_burst(x,y,0);Wave*w=waves+(waveHead+63)%64;w->radius=radius;w->life=.65f;}
void pc_torpedo_blast(int x,int y){pc_burst(x,y,1);Wave*w=waves+(waveHead+63)%64;w->radius=48;w->life=.8f;}
void pc_mine_blast(int x,int y){pc_charge_burst(x,y);pc_mine_sound(x);Wave*w=waves+(waveHead+63)%64;w->radius=14;w->life=.35f;}
void pc_bomb_start(int x,int y){for(int i=0;i<480;i++){float a=frand()*2*PI,s=25+frand()*180;emit(x,y,cosf(a)*s,sinf(a)*s*.8f,.3f+frand()*.8f,.6f+frand()*2,3);}}
