void pc_charge_burst(int x,int y){lastExplosionX=(float)x;if(!g.fx)return;for(int i=0;i<60;i++){float a=frand()*2*PI,s=12+frand()*65;emit(x,y,cosf(a)*s,sinf(a)*s,.15f+frand()*.45f,.4f+frand()*1.1f,(i&3)?1:3);}Wave*w=waves+waveHead;waveHead=(waveHead+1)%64;*w=(Wave){x,y,0,.45f,25,0};}
/* A stable hull in each phase: only blend during the actual transformation. */
static float smooth_unit(float t){t=fmaxf(0,fminf(1,t));return t*t*(3-2*t);}
void pc_enemy_sprite(int n,Obj*o,float x,float y){if(organic_context()){int cell=organic_cell(o);n=137+cell;if(ndraw<256)draws[ndraw++]=(Draw){n,x,y,o->heading/16.0f+(floor_enemy(o)?0:180),o->type==4?1+o->power/640.0f:1,1,.enemy=1,.damageUntil=o->damageUntil};return;}if(o->type==26){if(ndraw<256)draws[ndraw++]=(Draw){28,x,y,atan2f((float)o->vy,(float)o->vx)*180/PI-90,.24f,1,.enemy=1,.damageUntil=o->damageUntil};return;}if(ndraw>=254||n<0||n>=137)return;float angle=o->heading/16.0f+(((n>=40&&n<50)||n>=65)?180:0);if(o->type!=4){draws[ndraw++]=(Draw){n,x,y,angle,1,1,.enemy=1,.damageUntil=o->damageUntil,.strength=o->strength>0?o->strength:0};return;}float form=o->power/256.0f;int stage=form>=1?1:0;float blend=smooth_unit(form-stage),growth=1+.42f*(stage+blend),breath=1+.004f*sinf(visualTick*.055f+o->variant);int from=o->variant>=12?121+(o->variant-12)*3+stage:stage?67+o->variant:n,to=o->variant>=12?from+1:67+stage*12+o->variant;if(blend<.9999f)draws[ndraw++]=(Draw){from,x,y,angle,growth*breath,1-blend,.enemy=1,.damageUntil=o->damageUntil};if(blend>.0001f)draws[ndraw++]=(Draw){to,x,y,angle,growth*breath,blend,.enemy=1,.damageUntil=o->damageUntil};}
