 beam_ribbon(x,tip,xx,end,width*1.9f,(SDL_FColor){c.r,c.g,c.b,.5f});
 beam_ribbon(x,tip,xx,end,width*1.18f,(SDL_FColor){c.r,c.g,c.b,.92f});
