/* Mission opening only: a brief ease-in, hold, then a two-second return to 1:1.
 * The exact zero before combat avoids residual zoom or changed collision bounds. */
static float opening_closeup(float alpha){
 if(reducedMotion||g.mode!=1||ex.section||!ex.intro||ex.travel||ex.refit||ex.victory||ex.bossSpawned)return 0;
 float remaining=ex.intro;if(previousEx.intro>0)remaining=previousEx.intro+(ex.intro-previousEx.intro)*alpha;
 float start=ex.missionHandover?250:400;
 return smooth_unit(fmaxf(0,fminf(1,(start-remaining)/25)))*smooth_unit(fmaxf(0,fminf(1,(remaining-10)/100)));
}
